    pos: usize,
    // Stack of lexing contexts
    // When we see ${ in a string, push a regular context and mark the string
    // when we see the matching } from interpol, we pop back to string mode.
    ctx_stack: Vec<Context>,
}

#[derive(Debug, Clone, Copy)]
enum Context {
    // Standard nix code (default)
    Code,
    // Inside a string literal
    String(StringCtx),
    // Inside ${...} which nests code inside a string
    Interpol(StringCtx, usize /* brace depth */),
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8]) -> Self {
        Lexer { src, pos: 0, ctx_stack: vec![Context::Code] }
    }

    fn peek(&self, off: usize) -> Option<u8> {
        self.src.get(self.pos + off).copied()
    }

    fn bump(&mut self) -> Option<u8> {
        let c = self.peek(0)?;
        self.pos += 1;
        Some(c)
    }

    fn starts_with(&self, s: &[u8]) -> bool {
        self.src[self.pos..].starts_with(s)
    }

    pub fn next_token(&mut self) -> Lexeme {
        let start = self.pos;
        if self.pos >= self.src.len() {
            return Lexeme { tok: Token::Eof, span: start..start };
        }

        let ctx = *self.ctx_stack.last().unwrap();

        match ctx {
            Context::String(which) => self.lex_string_content(which),
            Context::Code | Context::Interpol(_, _) => self.lex_code(),
        }
    }

    fn lex_code(&mut self) -> Lexeme {
        let start = self.pos;
        let c = self.src[self.pos];

        // Whitespace
        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
            while let Some(c) = self.peek(0) {
                if matches!(c, b' ' | b'\t' | b'\n' | b'\r') {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            return Lexeme { tok: Token::Whitespace, span: start..self.pos };
        }

        // Line comment
        if c == b'#' {
            while let Some(c) = self.peek(0) {
                if c == b'\n' { break; }
                self.pos += 1;
            }
            return Lexeme { tok: Token::LineComment, span: start..self.pos };
        }

        // Block comment
        if c == b'/' && self.peek(1) == Some(b'*') {
            self.pos += 2;
            while self.pos < self.src.len() {
                if self.starts_with(b"*/") {
                    self.pos += 2;
                    return Lexeme { tok: Token::BlockComment, span: start..self.pos };
                }
                self.pos += 1;
            }
            return Lexeme { tok: Token::BlockComment, span: start..self.pos };
        }

        // Strings
        if c == b'"' {
            self.pos += 1;
            self.ctx_stack.push(Context::String(StringCtx::Quote));
            return Lexeme { tok: Token::StringStart, span: start..self.pos };
        }

        // Indented string ''
        if c == b'\'' && self.peek(1) == Some(b'\'') {
            self.pos += 2;
            self.ctx_stack.push(Context::String(StringCtx::Indent));
            return Lexeme { tok: Token::IndentStart, span: start..self.pos };
        }

        // ${ for interpolation start - but only meaningful inside strings.
        // If we see it in code, unlikely; parser will handle errors.

        // Brace handling - matches interpolation
        if c == b'{' {
            // If we're inside an interpol context, increment brace depth
            if let Some(Context::Interpol(_, _)) = self.ctx_stack.last() {
                if let Some(Context::Interpol(ws, depth)) = self.ctx_stack.pop() {
                    self.ctx_stack.push(Context::Interpol(ws, depth + 1));
                }
            }
            self.pos += 1;
            return Lexeme { tok: Token::LBrace, span: start..self.pos };
        }
        if c == b'}' {
            // If we're in an interpol, dec depth or close interpol
            if let Some(Context::Interpol(ws, depth)) = self.ctx_stack.last().copied() {
                if depth == 0 {
                    self.ctx_stack.pop();
                    // The string context should still be on the stack
                    self.pos += 1;
                    return Lexeme { tok: Token::InterpolEnd, span: start..self.pos };
                } else {
                    self.ctx_stack.pop();
                    self.ctx_stack.push(Context::Interpol(ws, depth - 1));
                }
            }
            self.pos += 1;
            return Lexeme { tok: Token::RBrace, span: start..self.pos };
        }

        // ${ - interp start (inside code means not applicable, but handle just in case)
        if c == b'$' && self.peek(1) == Some(b'{') {
            self.pos += 2;
            // If outer is string, push Interpol with matching whitespace
            let ws = match self.ctx_stack.last() {
                Some(&Context::String(ws)) => Some(ws),
                _ => None,
            };
            if let Some(ws) = ws {
                self.ctx_stack.push(Context::Interpol(ws, 0));
            }
            return Lexeme { tok: Token::InterpolStart, span: start..self.pos };
        }

        // Ellipsis
        if self.starts_with(b"...") {
            self.pos += 3;
            return Lexeme { tok: Token::Ellipsis, span: start..self.pos };
        }

        // Search path <...>
        if c == b'<' {
            // Attempt to match <path>  with path chars
            let save = self.pos;
            self.pos += 1;
            let inner_start = self.pos;
            let mut ok = false;
            while let Some(ch) = self.peek(0) {
                if ch.is_ascii_alphanumeric() || matches!(ch, b'_' | b'-' | b'.' | b'+' | b'/') {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            if self.pos > inner_start && self.peek(0) == Some(b'>') {
                self.pos += 1;
                ok = true;
            }
            if ok {
                return Lexeme { tok: Token::SearchPath, span: start..self.pos };
            }
            // rollback
            self.pos = save;
        }

        // Number or Path
        // Path detection: starts with [a-zA-Z0-9._+-]* / ...   or / ... or ~...
        // But also float: digits . digits
        if c == b'/' {
            // Absolute path /foo/bar  -- must not be followed by '*' (already handled block comment)
            // and must not be followed by '/' (that's update //)
            if self.peek(1) == Some(b'/') {
                self.pos += 2;
                return Lexeme { tok: Token::Update, span: start..self.pos };
            }
            // Try to match /path
            let save = self.pos;
            self.pos += 1;
            if let Some(ch) = self.peek(0) {
                if ch.is_ascii_alphanumeric() || matches!(ch, b'_' | b'-' | b'.' | b'+') {
                    // absolute path
                    while let Some(ch) = self.peek(0) {
                        if ch.is_ascii_alphanumeric() || matches!(ch, b'_' | b'-' | b'.' | b'+' | b'/') {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                    return Lexeme { tok: Token::Path, span: start..self.pos };
                }
            }
            self.pos = save;
            // It's a Slash
            self.pos += 1;
            return Lexeme { tok: Token::Slash, span: start..self.pos };
        }

        // Path starting with ~/  or ./
        if c == b'~' && self.peek(1) == Some(b'/') {
            self.pos += 2;
            while let Some(ch) = self.peek(0) {
                if ch.is_ascii_alphanumeric() || matches!(ch, b'_' | b'-' | b'.' | b'+' | b'/') {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            return Lexeme { tok: Token::Path, span: start..self.pos };
        }

        // Numbers and paths starting with a digit or letter
        if c.is_ascii_digit() {
            // Could be int, float, or path
            // Look ahead: if contains . followed by digit, it could be a float
            // If contains / followed by path char, it's a path
            let save = self.pos;
            let mut has_dot = false;
            let mut is_path = false;
            let mut i = self.pos;
            while i < self.src.len() {
                let ch = self.src[i];
                if ch.is_ascii_digit() {
                    i += 1;
                } else if ch == b'.' && !has_dot {
                    if let Some(&ch2) = self.src.get(i+1) {
                        if ch2.is_ascii_digit() {
                            has_dot = true;
                            i += 1;
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                } else if matches!(ch, b'_' | b'-' | b'+' | b'/') || ch.is_ascii_alphabetic() {
                    // Maybe a path.
                    // Scan forward to see if we encounter a '/'
                    let mut j = i;
                    while j < self.src.len() {
                        let cj = self.src[j];
                        if cj.is_ascii_alphanumeric() || matches!(cj, b'_' | b'-' | b'.' | b'+') {
                            j += 1;
                        } else if cj == b'/' {
                            is_path = true;
                            break;
                        } else {
                            break;
                        }
                    }
                    break;
                } else {
                    break;
                }
            }

            if is_path {
                // Consume path chars
                self.pos = save;
                while let Some(ch) = self.peek(0) {
                    if ch.is_ascii_alphanumeric() || matches!(ch, b'_' | b'-' | b'.' | b'+' | b'/') {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                return Lexeme { tok: Token::Path, span: start..self.pos };
            }
            // Consume digits (and optional decimal point)
            while let Some(ch) = self.peek(0) {
                if ch.is_ascii_digit() {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            if self.peek(0) == Some(b'.') && self.peek(1).map_or(false, |c| c.is_ascii_digit()) {
                self.pos += 1;
                while let Some(ch) = self.peek(0) {
                    if ch.is_ascii_digit() {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                // optional exponent
                if matches!(self.peek(0), Some(b'e' | b'E')) {
                    self.pos += 1;
                    if matches!(self.peek(0), Some(b'+' | b'-')) {
                        self.pos += 1;
                    }
                    while let Some(ch) = self.peek(0) {
                        if ch.is_ascii_digit() { self.pos += 1; } else { break; }
                    }
                }
                return Lexeme { tok: Token::Float, span: start..self.pos };
            }
            return Lexeme { tok: Token::Integer, span: start..self.pos };
        }

        // Identifier or path/uri
        if c.is_ascii_alphabetic() || c == b'_' {
            // Consume identifier chars
            let mut i = self.pos + 1;
            while i < self.src.len() {
                let ch = self.src[i];
                if ch.is_ascii_alphanumeric() || matches!(ch, b'_' | b'\'' | b'-') {
                    i += 1;
                } else {
                    break;
                }
            }
            // Check for URI: scheme:path where scheme = ident, followed by :, then URI chars
            // Looking at `scheme:` pattern where the following chars look URI-y
            let after_ident = i;
            if after_ident < self.src.len() && self.src[after_ident] == b':' {
                // Check next char is not whitespace/EOF/special (which would be a regular colon)
                if let Some(&cc) = self.src.get(after_ident + 1) {
                    // Looks like URI if the next is alphanumeric and then contains a '/'
                    if cc.is_ascii_alphanumeric() || matches!(cc, b'/' | b'?' | b':' | b'%' | b'+' | b'-' | b'.' | b'~' | b'#' | b'_' | b'!' | b'$' | b'&' | b'\'' | b'*' | b'=' | b'@' | b',' | b';') {
                        // only treat as URI if there's a '/' or '?' or similar in the next few chars
                        // Actually, Nix URIs: [a-zA-Z][a-zA-Z0-9+\-.]*:[a-zA-Z0-9%/?:@&=+$,\-_.!~*']+
                        // Must have at least one URI char after :
                        let mut j = after_ident + 1;
                        let uri_start = j;
                        while j < self.src.len() {
                            let cj = self.src[j];
                            if cj.is_ascii_alphanumeric() || matches!(cj, b'%' | b'/' | b'?' | b':' | b'@' | b'&' | b'=' | b'+' | b'$' | b',' | b'-' | b'_' | b'.' | b'!' | b'~' | b'*' | b'\'') {
                                j += 1;
                            } else {
                                break;
                            }
                        }
                        // Require at least one URI char and require that somewhere it has a non-ident-like char (like / or ? or @)
                        if j > uri_start {
                            // Heuristic: require a `/` in URI or `?` or `@` or `:` (port)
                            let slice = &self.src[uri_start..j];
                            if slice.iter().any(|&c| c == b'/' || c == b'?' || c == b'@' || c == b':') {
                                self.pos = j;
                                return Lexeme { tok: Token::Uri, span: start..self.pos };
                            }
                        }
                    }
                }
            }

            // Check path: ident/path...
            // Actually only if we have ident followed by / then alphanumeric
            // Look ahead
            if i < self.src.len() && self.src[i] == b'/' && self.src.get(i+1).map_or(false, |&c| c.is_ascii_alphanumeric() || matches!(c, b'_' | b'-' | b'.' | b'+')) {
                // Path
                self.pos = i + 1;
                while let Some(ch) = self.peek(0) {
                    if ch.is_ascii_alphanumeric() || matches!(ch, b'_' | b'-' | b'.' | b'+' | b'/') {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                return Lexeme { tok: Token::Path, span: start..self.pos };
            }

            self.pos = i;
            return Lexeme { tok: Token::Ident, span: start..self.pos };
        }

        // Punctuation
        let two = &self.src[self.pos..std::cmp::min(self.pos+2, self.src.len())];
        let tok_info: Option<(Token, usize)> = match two {
            b"++" => Some((Token::Concat, 2)),
            b"==" => Some((Token::Equal, 2)),
            b"!=" => Some((Token::NotEqual, 2)),
            b"<=" => Some((Token::LessEq, 2)),
            b">=" => Some((Token::GreaterEq, 2)),
            b"&&" => Some((Token::And, 2)),
            b"||" => Some((Token::Or, 2)),
            b"->" => Some((Token::Implies, 2)),
            _ => None,
        };
        if let Some((t, n)) = tok_info {
            self.pos += n;
            return Lexeme { tok: t, span: start..self.pos };
        }

        let (t, n) = match c {
            b'(' => (Token::LParen, 1),
            b')' => (Token::RParen, 1),
            b'[' => (Token::LBrack, 1),
            b']' => (Token::RBrack, 1),
            b';' => (Token::Semicolon, 1),
            b',' => (Token::Comma, 1),
            b':' => (Token::Colon, 1),
            b'.' => (Token::Dot, 1),
            b'@' => (Token::At, 1),
            b'?' => (Token::Question, 1),
            b'=' => (Token::Assign, 1),
            b'+' => (Token::Plus, 1),
            b'-' => (Token::Minus, 1),
            b'*' => (Token::Star, 1),
            b'<' => (Token::Less, 1),
            b'>' => (Token::Greater, 1),
            b'!' => (Token::Not, 1),
            _ => (Token::Error, 1),
        };
        self.pos += n;
        Lexeme { tok: t, span: start..self.pos }
    }

    fn lex_string_content(&mut self, which: StringCtx) -> Lexeme {
        let start = self.pos;
        match which {
            StringCtx::Quote => {
                // End on unescaped " or ${
                // First check for end
                if self.peek(0) == Some(b'"') {
                    self.pos += 1;
                    self.ctx_stack.pop();
                    return Lexeme { tok: Token::StringEnd, span: start..self.pos };
                }
                if self.peek(0) == Some(b'$') && self.peek(1) == Some(b'{') {
                    self.pos += 2;
                    self.ctx_stack.push(Context::Interpol(which, 0));
                    return Lexeme { tok: Token::InterpolStart, span: start..self.pos };
                }
                while self.pos < self.src.len() {
                    let c = self.src[self.pos];
                    if c == b'\\' {
                        self.pos += 1;
                        if self.pos < self.src.len() {
                            self.pos += 1;
                        }
                    } else if c == b'"' {
                        break;
                    } else if c == b'$' && self.peek(1) == Some(b'{') {
                        break;
                    } else {
                        self.pos += 1;
                    }
                }
                Lexeme { tok: Token::StringContent, span: start..self.pos }
            }
            StringCtx::Indent => {
                // End on '' (but not ''${ or ''' or ''\)
                if self.peek(0) == Some(b'\'') && self.peek(1) == Some(b'\'') {
                    // Check for escape forms ''${, ''', ''\, ''$
                    match self.peek(2) {
                        Some(b'$') | Some(b'\'') | Some(b'\\') => {
                            // escape, continue reading content
                        }
                        _ => {
                            self.pos += 2;
                            self.ctx_stack.pop();
                            return Lexeme { tok: Token::IndentEnd, span: start..self.pos };
                        }
                    }
                }
                if self.peek(0) == Some(b'$') && self.peek(1) == Some(b'{') {
                    self.pos += 2;
                    self.ctx_stack.push(Context::Interpol(which, 0));
                    return Lexeme { tok: Token::InterpolStart, span: start..self.pos };
                }
                while self.pos < self.src.len() {
                    let c = self.src[self.pos];
                    if c == b'\'' && self.peek(1) == Some(b'\'') {
                        // Check escape
                        match self.peek(2) {
                            Some(b'$') | Some(b'\'') | Some(b'\\') => {
                                self.pos += 3;
                            }
                            _ => break, // end of string
                        }
                    } else if c == b'$' && self.peek(1) == Some(b'{') {
                        break;
                    } else {
                        self.pos += 1;
                    }
                }
                Lexeme { tok: Token::StringContent, span: start..self.pos }
            }
        }
    }
}

pub fn classify_keyword(s: &str) -> Option<Token> {
    match s {
        "let" => Some(Token::KwLet),
        "in" => Some(Token::KwIn),
        "rec" => Some(Token::KwRec),
        "with" => Some(Token::KwWith),
        "inherit" => Some(Token::KwInherit),
        "if" => Some(Token::KwIf),
        "then" => Some(Token::KwThen),
        "else" => Some(Token::KwElse),
        "assert" => Some(Token::KwAssert),
        "or" => Some(Token::KwOr),
        "true" => Some(Token::KwTrue),
        "false" => Some(Token::KwFalse),
        "null" => Some(Token::KwNull),
        _ => None,
    }
}
