// Nix AST (simplified, for dead-code analysis)

use std::ops::Range;

#[derive(Debug, Clone)]
pub enum Expr {
    Literal(Range<usize>), // integer, float, string (plain), path, uri, null, true, false
    // A segmented string (may have interpolations)
    Str {
        span: Range<usize>,
        parts: Vec<StrPart>,
    },
    Ident {
        span: Range<usize>,
