    AttrSet {
        span: Range<usize>,
        rec: bool,
        rec_kw_span: Option<Range<usize>>, // location of `rec`
        bindings: Vec<Binding>,
    },
    // List
    List {
        span: Range<usize>,
        elements: Vec<Expr>,
    },
    // Lambda
    Lambda {
        span: Range<usize>,
        param: LambdaParam,
        body: Box<Expr>,
    },
    // Application f x
    Apply {
        span: Range<usize>,
        func: Box<Expr>,
        arg: Box<Expr>,
    },
    // f.x
    Select {
        span: Range<usize>,
        expr: Box<Expr>,
        path: Vec<AttrName>,
        default: Option<Box<Expr>>, // `or default`
    },
    // Binary op
    BinOp {
        span: Range<usize>,
        op: BinOp,
        lhs: Box<Expr>,
        rhs: Box<Expr>,
    },
    // Unary op
    UnaryOp {
        span: Range<usize>,
        op: UnaryOp,
        expr: Box<Expr>,
    },
    // if cond then t else f
    If {
        span: Range<usize>,
        cond: Box<Expr>,
        then_branch: Box<Expr>,
        else_branch: Box<Expr>,
    },
    // with e; body
    With {
        span: Range<usize>,
        expr: Box<Expr>,
        body: Box<Expr>,
    },
    // assert e; body
    Assert {
        span: Range<usize>,
        cond: Box<Expr>,
        body: Box<Expr>,
    },
    // has-attr e ? path
    HasAttr {
        span: Range<usize>,
        expr: Box<Expr>,
        path: Vec<AttrName>,
    },
    // Parenthesized
    Paren {
        span: Range<usize>,
        expr: Box<Expr>,
    },
    // Error: an expression we couldn't parse
    Error(Range<usize>),
}

#[derive(Debug, Clone)]
pub enum StrPart {
    Literal(Range<usize>),
    Interp(Range<usize>, Expr), // span is the whole ${...}, expr is inner
}

#[derive(Debug, Clone)]
pub struct Binding {
    pub kind: BindingKind,
    pub span: Range<usize>, // whole binding, including trailing `;`
}

#[derive(Debug, Clone)]
pub enum BindingKind {
    AttrBinding {
        path: Vec<AttrName>,
        // The first attr in the path, if it's a simple ident, is the bound name for the
        // purpose of a let binding.
        value: Expr,
    },
    Inherit {
        // None = plain inherit (inherit a b;), Some = inherit (expr) a b;
        from: Option<Expr>,
        attrs: Vec<AttrName>,
    },
}

#[derive(Debug, Clone)]
pub enum AttrName {
    // Plain ident: e.g. `a`
    Ident { span: Range<usize>, name: String },
    // Static string: e.g. `"foo"`
    Str { span: Range<usize>, value: String },
    // Dynamic: `${expr}`
    Dynamic { span: Range<usize>, expr: Expr },
}

impl AttrName {
    pub fn span(&self) -> Range<usize> {
        match self {
            AttrName::Ident { span, .. } => span.clone(),
            AttrName::Str { span, .. } => span.clone(),
            AttrName::Dynamic { span, .. } => span.clone(),
        }
    }
    pub fn as_ident(&self) -> Option<(&Range<usize>, &str)> {
        match self {
            AttrName::Ident { span, name } => Some((span, name.as_str())),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct LambdaParam {
    pub span: Range<usize>,
    pub kind: ParamKind,
}

#[derive(Debug, Clone)]
pub enum ParamKind {
    // x:
    Ident { span: Range<usize>, name: String },
    // {a, b ? d, ...}@args: or {...}: or args@{...}:
    Pattern {
        // The `name@` binding (if any)
        at_binding: Option<AtBinding>,
        entries: Vec<PatternEntry>,
        ellipsis: bool,
        // location of the outer `{ ... }` including at_binding
        lbrace: Range<usize>,
        rbrace: Range<usize>,
    },
}

#[derive(Debug, Clone)]
pub struct AtBinding {
    pub name: String,
    pub ident_span: Range<usize>, // just the ident
    pub at_span: Range<usize>,    // just the @
    pub before: bool,             // args@{...} (true) vs {...}@args (false)
    // Spans covering the entire "ident@" (or "@ident") fragment, with trailing/leading whitespace, for editing
    pub full_span: Range<usize>,
}

#[derive(Debug, Clone)]
pub struct PatternEntry {
    pub name: String,
    pub ident_span: Range<usize>,
    pub default: Option<Expr>,
    // The full span covering the entry itself (ident + optional default), not trailing commas
    pub span: Range<usize>,
    // Span of the entry plus the trailing `,` (or just entry if last)
    // Used for editing.
    pub span_with_sep: Range<usize>,
    // Span of the entry plus the leading `,` (for editing when removing)
    pub span_with_prev_sep: Range<usize>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BinOp {
    Add, Sub, Mul, Div,
    Concat, Update,
    Eq, Ne, Lt, Gt, Le, Ge,
    And, Or, Implies,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UnaryOp {
    Neg,
    Not,
}

impl Expr {
    pub fn span(&self) -> Range<usize> {
        match self {
            Expr::Literal(s) => s.clone(),
            Expr::Str { span, .. } => span.clone(),
            Expr::Ident { span, .. } => span.clone(),
            Expr::Let { span, .. } => span.clone(),
            Expr::AttrSet { span, .. } => span.clone(),
            Expr::List { span, .. } => span.clone(),
            Expr::Lambda { span, .. } => span.clone(),
            Expr::Apply { span, .. } => span.clone(),
            Expr::Select { span, .. } => span.clone(),
            Expr::BinOp { span, .. } => span.clone(),
            Expr::UnaryOp { span, .. } => span.clone(),
            Expr::If { span, .. } => span.clone(),
            Expr::With { span, .. } => span.clone(),
            Expr::Assert { span, .. } => span.clone(),
            Expr::HasAttr { span, .. } => span.clone(),
            Expr::Paren { span, .. } => span.clone(),
            Expr::Error(s) => s.clone(),
        }
    }
}
