// Recursive descent Nix parser

use crate::ast::*;
use crate::lexer::{Lexer, Lexeme, Token, classify_keyword};
use std::ops::Range;

pub struct ParseError {
    pub span: Range<usize>,
    pub message: String,
}

pub struct Parser<'a> {
    src: &'a [u8],
    tokens: Vec<Lexeme>,  // filtered (no whitespace/comments)
    raw_tokens: Vec<Lexeme>, // all tokens
    pos: usize,
    pub errors: Vec<ParseError>,
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a [u8]) -> Self {
        let mut lexer = Lexer::new(src);
        let mut raw = Vec::new();
        loop {
            let lx = lexer.next_token();
            if lx.tok == Token::Eof { raw.push(lx); break; }
            raw.push(lx);
        }
        // Filter out whitespace/comments into tokens
        let tokens: Vec<Lexeme> = raw.iter()
            .filter(|l| !matches!(l.tok, Token::Whitespace | Token::LineComment | Token::BlockComment))
            .cloned()
            .collect();
        Parser { src, tokens, raw_tokens: raw, pos: 0, errors: Vec::new() }
    }

    pub fn raw_tokens(&self) -> &[Lexeme] { &self.raw_tokens }

    fn peek(&self, off: usize) -> Token {
        self.tokens.get(self.pos + off).map(|l| l.tok).unwrap_or(Token::Eof)
    }

    fn peek_span(&self, off: usize) -> Range<usize> {
        self.tokens.get(self.pos + off).map(|l| l.span.clone()).unwrap_or_else(|| {
            let end = self.src.len();
            end..end
        })
    }

    fn bump(&mut self) -> Lexeme {
        let lx = self.tokens.get(self.pos).cloned().unwrap_or_else(|| {
            let end = self.src.len();
            Lexeme { tok: Token::Eof, span: end..end }
        });
        if self.pos < self.tokens.len() {
            self.pos += 1;
        }
        lx
    }

    fn eat(&mut self, t: Token) -> bool {
        if self.peek(0) == t {
            self.bump();
            true
        } else {
            false
        }
    }

    fn expect(&mut self, t: Token) -> bool {
        if self.eat(t) { true } else {
            let sp = self.peek_span(0);
            self.errors.push(ParseError {
                span: sp,
                message: format!("expected {:?}", t),
            });
            false
        }
    }

    fn slice(&self, r: &Range<usize>) -> &str {
        std::str::from_utf8(&self.src[r.start..r.end]).unwrap_or("")
    }

    pub fn parse(&mut self) -> Expr {
        let e = self.parse_expr();
        if self.peek(0) != Token::Eof {
            // trailing tokens?
        }
        e
    }

    // Entry: highest level expression
    fn parse_expr(&mut self) -> Expr {
        self.parse_function()
    }

    fn parse_function(&mut self) -> Expr {
        let start = self.peek_span(0).start;

        // Handle: ident ':' expr, ident '@' '{' pattern '}' ':' expr,  '{' pattern '}' optionalAt ':' expr
        // Look ahead heuristically
        if self.peek(0) == Token::Ident {
            // ident ':' expr ... (plain lambda)
            if self.peek(1) == Token::Colon {
                let id = self.bump();
                self.bump(); // colon
                let body = self.parse_function();
                let name = self.slice(&id.span).to_string();
                let param = LambdaParam {
                    span: id.span.clone(),
                    kind: ParamKind::Ident { span: id.span.clone(), name },
                };
                let end = body.span().end;
                return Expr::Lambda { span: start..end, param, body: Box::new(body) };
            }
            // ident '@' '{' ...
            if self.peek(1) == Token::At && self.peek(2) == Token::LBrace {
                let id = self.bump();
                let at = self.bump();
                // parse pattern
                return self.parse_lambda_pattern(start, Some((id, at, true)));
            }
        }
        if self.peek(0) == Token::LBrace {
            // Could be a pattern lambda or an attrset expression.
            // We need to look further. Pattern lambda form: '{' (ident (',' ident)*)? '}' (@ ident)? ':' ...
            // Attrset: '{' binds '}'
            // Disambiguate: if we see '{' followed by '}' followed by ':' -> lambda
            //               or '{' '...' '}' -> lambda
            //               or '{' ident (',' | '?' | '}') -> 
            //                    next should be ':' (lambda) or '=' (binding attrset)
            //                    if ident followed by '=' -> attrset; if ',', '?', '...' -> lambda
            if self.looks_like_pattern_lambda() {
                return self.parse_lambda_pattern(start, None);
            }
        }

        if self.peek(0) == Token::KwLet {
            // let ... in ...  (could also be `let { ... }` legacy form)
            let let_kw = self.bump();
            // legacy: let { ... }
            if self.peek(0) == Token::LBrace {
                let l = self.bump();
                let bindings = self.parse_bindings_until(Token::RBrace);
                let r = self.bump(); // consume `}`
                let end = r.span.end;
                // Represent as a rec set with __main__ or similar... for analysis, treat as rec set.
                return Expr::AttrSet {
                    span: start..end,
                    rec: true,
                    rec_kw_span: Some(let_kw.span.clone()),
                    bindings,
                };
            }
            let bindings = self.parse_bindings_until(Token::KwIn);
            if !self.eat(Token::KwIn) {
                let sp = self.peek_span(0);
                self.errors.push(ParseError { span: sp, message: "expected `in`".into() });
            }
            let body = self.parse_function();
            let end = body.span().end;
            return Expr::Let {
                span: start..end,
                bindings,
                body: Box::new(body),
            };
        }

        if self.peek(0) == Token::KwWith {
            self.bump();
            let e = self.parse_op();
            if !self.eat(Token::Semicolon) {
                let sp = self.peek_span(0);
                self.errors.push(ParseError { span: sp, message: "expected `;` after `with`".into() });
            }
            let body = self.parse_function();
            let end = body.span().end;
            return Expr::With { span: start..end, expr: Box::new(e), body: Box::new(body) };
        }
        if self.peek(0) == Token::KwAssert {
            self.bump();
            let e = self.parse_op();
            if !self.eat(Token::Semicolon) {
                let sp = self.peek_span(0);
                self.errors.push(ParseError { span: sp, message: "expected `;` after assert".into() });
            }
            let body = self.parse_function();
            let end = body.span().end;
            return Expr::Assert { span: start..end, cond: Box::new(e), body: Box::new(body) };
        }

        self.parse_if()
    }

    fn parse_lambda_pattern(&mut self, start: usize, at_prefix: Option<(Lexeme, Lexeme, bool)>) -> Expr {
        // Assumes we're at `{`
        let lbrace = self.bump();
        let mut entries: Vec<PatternEntry> = Vec::new();
        let mut ellipsis = false;
        let mut entry_start_positions: Vec<usize> = Vec::new(); // positions of start of each entry (useful for editing separators)
        loop {
            if self.peek(0) == Token::RBrace {
                break;
            }
            if self.peek(0) == Token::Ellipsis {
                self.bump();
                ellipsis = true;
                // optionally trailing comma not allowed after ellipsis
                break;
            }
            if self.peek(0) != Token::Ident {
                // error
                let sp = self.peek_span(0);
                self.errors.push(ParseError { span: sp.clone(), message: "expected identifier in pattern".into() });
                // try to skip to next comma or rbrace
                let start_err = sp.start;
                while !matches!(self.peek(0), Token::Comma | Token::RBrace | Token::Eof) {
                    self.bump();
                }
                entries.push(PatternEntry {
                    name: "".into(),
                    ident_span: start_err..start_err,
                    default: None,
                    span: start_err..start_err,
                    span_with_sep: start_err..start_err,
                    span_with_prev_sep: start_err..start_err,
                });
                if self.peek(0) == Token::Comma {
                    self.bump();
                    continue;
                } else {
                    break;
                }
            }
            let entry_start = self.peek_span(0).start;
            entry_start_positions.push(entry_start);
            let id = self.bump();
            let name = self.slice(&id.span).to_string();
            let mut default: Option<Expr> = None;
            let mut entry_end = id.span.end;
            if self.peek(0) == Token::Question {
                self.bump();
                let e = self.parse_op();
                entry_end = e.span().end;
                default = Some(e);
            }
            let had_trailing_comma = self.peek(0) == Token::Comma;
            let comma_span = if had_trailing_comma { Some(self.peek_span(0)) } else { None };
            if had_trailing_comma {
                self.bump();
            }
            // span_with_sep: from entry start to after comma (if present)
            let sep_end = match &comma_span { Some(r) => r.end, None => entry_end };
            // Also include whitespace after the comma up to the next entry start or `}`
            let sep_end_with_ws = if had_trailing_comma {
                // include whitespace up to next token
                self.tokens.get(self.pos).map(|l| l.span.start).unwrap_or(sep_end)
            } else {
                sep_end
            };
            entries.push(PatternEntry {
                name,
                ident_span: id.span.clone(),
                default,
                span: entry_start..entry_end,
                span_with_sep: entry_start..sep_end_with_ws,
                span_with_prev_sep: entry_start..entry_end, // to be fixed up after loop
            });
            if !had_trailing_comma {
                break;
            }
        }
        // Fix up span_with_prev_sep for each non-first entry
        // Actually span_with_prev_sep is entry_prev_end .. entry_end
        // Let me compute: for entry i>0, span_with_prev_sep.start = entries[i-1].span.end
        // But we need to include the comma before this entry.
        for i in 0..entries.len() {
            if i == 0 {
                // first entry, no previous separator
                entries[i].span_with_prev_sep = entries[i].span.clone();
            } else {
                let prev_end = entries[i-1].span.end;
                entries[i].span_with_prev_sep = prev_end..entries[i].span.end;
            }
        }

        if self.peek(0) != Token::RBrace {
            let sp = self.peek_span(0);
            self.errors.push(ParseError { span: sp, message: "expected `}` in pattern".into() });
        }
        let rbrace = self.bump(); // consume `}`

        // Optional @binding after
        let at_binding = if let Some((id, at, before)) = at_prefix {
            // Compute full_span including any whitespace between id and {
            // from id.span.start .. lbrace.span.start (includes @ and whitespace)
            Some(AtBinding {
                name: self.slice(&id.span).to_string(),
                ident_span: id.span.clone(),
                at_span: at.span.clone(),
                before,
                full_span: id.span.start..lbrace.span.start,
            })
        } else if self.peek(0) == Token::At && self.peek(1) == Token::Ident {
            let at = self.bump();
            let id = self.bump();
            // full_span covers whitespace before @ up to after id
            // We'll use rbrace.span.end .. id.span.end (from after `}` to end of id)
            Some(AtBinding {
                name: self.slice(&id.span).to_string(),
                ident_span: id.span.clone(),
                at_span: at.span.clone(),
                before: false,
                full_span: rbrace.span.end..id.span.end,
            })
        } else {
            None
        };

        if !self.eat(Token::Colon) {
            let sp = self.peek_span(0);
            self.errors.push(ParseError { span: sp, message: "expected `:` after pattern".into() });
        }
        let body = self.parse_function();
        let end = body.span().end;

        let pat_start = at_binding.as_ref().map(|a| if a.before { a.ident_span.start } else { lbrace.span.start }).unwrap_or(lbrace.span.start);
        let pat_end = at_binding.as_ref().map(|a| if a.before { rbrace.span.end } else { a.ident_span.end }).unwrap_or(rbrace.span.end);

        let param = LambdaParam {
            span: pat_start..pat_end,
            kind: ParamKind::Pattern {
                at_binding,
                entries,
                ellipsis,
                lbrace: lbrace.span.clone(),
                rbrace: rbrace.span.clone(),
            },
        };
        Expr::Lambda { span: start..end, param, body: Box::new(body) }
    }

    fn looks_like_pattern_lambda(&self) -> bool {
        // peek ahead at tokens
        let mut i = self.pos;
        // Consume '{'
        if self.tokens.get(i).map(|l| l.tok) != Some(Token::LBrace) { return false; }
        i += 1;
        // Empty { } : lambda iff followed by ':' (or @ ident :)
        if self.tokens.get(i).map(|l| l.tok) == Some(Token::RBrace) {
            let next = self.tokens.get(i+1).map(|l| l.tok);
            if next == Some(Token::Colon) { return true; }
            if next == Some(Token::At) {
                // need ident then colon
                if self.tokens.get(i+2).map(|l| l.tok) == Some(Token::Ident) {
                    return self.tokens.get(i+3).map(|l| l.tok) == Some(Token::Colon);
                }
            }
            return false;
        }
        // { ... }: -> lambda
        if self.tokens.get(i).map(|l| l.tok) == Some(Token::Ellipsis) { return true; }

        // { ident (stuff) }:
        if self.tokens.get(i).map(|l| l.tok) == Some(Token::Ident) {
            let next = self.tokens.get(i+1).map(|l| l.tok);
            match next {
                Some(Token::Comma) | Some(Token::Question) => return true,
                Some(Token::RBrace) => {
                    // could be either {x} : or {x} = 
                    // actually {x} alone isn't a valid attrset; `x` must be = value
                    // but `{x}` means a lambda with pattern {x}
                    // check what follows `}`:
                    let n2 = self.tokens.get(i+2).map(|l| l.tok);
                    if n2 == Some(Token::Colon) || n2 == Some(Token::At) {
                        return true;
                    }
                    return false;
                }
                Some(Token::Assign) => return false, // attrset
                Some(Token::Dot) => return false, // attrset (a.b = ...)
                _ => return false,
            }
        }
        // { "string" ... } -> attrset (can't be pattern)
        false
    }

    fn parse_if(&mut self) -> Expr {
        if self.peek(0) == Token::KwIf {
            let start = self.peek_span(0).start;
            self.bump();
            let cond = self.parse_expr();
            if !self.eat(Token::KwThen) {
                let sp = self.peek_span(0);
                self.errors.push(ParseError { span: sp, message: "expected `then`".into() });
            }
            let then_b = self.parse_expr();
            if !self.eat(Token::KwElse) {
                let sp = self.peek_span(0);
                self.errors.push(ParseError { span: sp, message: "expected `else`".into() });
            }
            let else_b = self.parse_expr();
            let end = else_b.span().end;
            return Expr::If { span: start..end, cond: Box::new(cond), then_branch: Box::new(then_b), else_branch: Box::new(else_b) };
        }
        self.parse_op()
    }

    // Operator precedence parsing
    fn parse_op(&mut self) -> Expr {
        self.parse_implies()
    }

    fn parse_implies(&mut self) -> Expr {
        // right-associative
        let lhs = self.parse_or();
        if self.peek(0) == Token::Implies {
            let start = lhs.span().start;
            self.bump();
            let rhs = self.parse_implies();
            let end = rhs.span().end;
            return Expr::BinOp { span: start..end, op: BinOp::Implies, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        lhs
    }

    fn parse_or(&mut self) -> Expr {
        let mut lhs = self.parse_and();
        while self.peek(0) == Token::Or {
            let start = lhs.span().start;
            self.bump();
            let rhs = self.parse_and();
            let end = rhs.span().end;
            lhs = Expr::BinOp { span: start..end, op: BinOp::Or, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        lhs
    }
    fn parse_and(&mut self) -> Expr {
        let mut lhs = self.parse_eq();
        while self.peek(0) == Token::And {
            let start = lhs.span().start;
            self.bump();
            let rhs = self.parse_eq();
            let end = rhs.span().end;
            lhs = Expr::BinOp { span: start..end, op: BinOp::And, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        lhs
    }
    fn parse_eq(&mut self) -> Expr {
        // non-associative (but we allow chaining for simplicity)
        let mut lhs = self.parse_cmp();
        loop {
            let op = match self.peek(0) {
                Token::Equal => BinOp::Eq,
                Token::NotEqual => BinOp::Ne,
                _ => break,
            };
            let start = lhs.span().start;
            self.bump();
            let rhs = self.parse_cmp();
            let end = rhs.span().end;
            lhs = Expr::BinOp { span: start..end, op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        lhs
    }
    fn parse_cmp(&mut self) -> Expr {
        let mut lhs = self.parse_update();
        loop {
            let op = match self.peek(0) {
                Token::Less => BinOp::Lt,
                Token::Greater => BinOp::Gt,
                Token::LessEq => BinOp::Le,
                Token::GreaterEq => BinOp::Ge,
                _ => break,
            };
            let start = lhs.span().start;
            self.bump();
            let rhs = self.parse_update();
            let end = rhs.span().end;
            lhs = Expr::BinOp { span: start..end, op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        lhs
    }
    fn parse_update(&mut self) -> Expr {
        // right-assoc
        let lhs = self.parse_not();
        if self.peek(0) == Token::Update {
            let start = lhs.span().start;
            self.bump();
            let rhs = self.parse_update();
            let end = rhs.span().end;
            return Expr::BinOp { span: start..end, op: BinOp::Update, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        lhs
    }
    fn parse_not(&mut self) -> Expr {
        if self.peek(0) == Token::Not {
            let start = self.peek_span(0).start;
            self.bump();
            let e = self.parse_not();
            let end = e.span().end;
            return Expr::UnaryOp { span: start..end, op: UnaryOp::Not, expr: Box::new(e) };
        }
        self.parse_add()
    }
    fn parse_add(&mut self) -> Expr {
        let mut lhs = self.parse_mul();
        loop {
            let op = match self.peek(0) {
                Token::Plus => BinOp::Add,
                Token::Minus => BinOp::Sub,
                _ => break,
            };
            let start = lhs.span().start;
            self.bump();
            let rhs = self.parse_mul();
            let end = rhs.span().end;
            lhs = Expr::BinOp { span: start..end, op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        lhs
    }
    fn parse_mul(&mut self) -> Expr {
        let mut lhs = self.parse_concat();
        loop {
            let op = match self.peek(0) {
                Token::Star => BinOp::Mul,
                Token::Slash => BinOp::Div,
                _ => break,
            };
            let start = lhs.span().start;
            self.bump();
            let rhs = self.parse_concat();
            let end = rhs.span().end;
            lhs = Expr::BinOp { span: start..end, op, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        lhs
    }
    fn parse_concat(&mut self) -> Expr {
        // right-assoc
        let lhs = self.parse_has_attr();
        if self.peek(0) == Token::Concat {
            let start = lhs.span().start;
            self.bump();
            let rhs = self.parse_concat();
            let end = rhs.span().end;
            return Expr::BinOp { span: start..end, op: BinOp::Concat, lhs: Box::new(lhs), rhs: Box::new(rhs) };
        }
        lhs
    }
    fn parse_has_attr(&mut self) -> Expr {
        let lhs = self.parse_neg();
        if self.peek(0) == Token::Question {
            let start = lhs.span().start;
            self.bump();
            let path = self.parse_attr_path();
            let end = path.last().map(|a| a.span().end).unwrap_or(lhs.span().end);
            return Expr::HasAttr { span: start..end, expr: Box::new(lhs), path };
        }
        lhs
    }
    fn parse_neg(&mut self) -> Expr {
        if self.peek(0) == Token::Minus {
            let start = self.peek_span(0).start;
            self.bump();
            let e = self.parse_neg();
            let end = e.span().end;
            return Expr::UnaryOp { span: start..end, op: UnaryOp::Neg, expr: Box::new(e) };
        }
        self.parse_app()
    }
    fn parse_app(&mut self) -> Expr {
        // Application: expr_select (expr_select)*
        let mut e = self.parse_select();
        loop {
            if self.can_start_simple() {
                let arg = self.parse_select();
                let start = e.span().start;
                let end = arg.span().end;
                e = Expr::Apply { span: start..end, func: Box::new(e), arg: Box::new(arg) };
            } else {
                break;
            }
        }
        e
    }

    fn can_start_simple(&self) -> bool {
        matches!(self.peek(0),
            Token::Ident | Token::Integer | Token::Float | Token::Path | Token::Uri | Token::SearchPath |
            Token::StringStart | Token::IndentStart | Token::LParen | Token::LBrace | Token::LBrack |
            Token::KwRec | Token::KwLet | Token::KwTrue | Token::KwFalse | Token::KwNull
        )
    }

    fn parse_select(&mut self) -> Expr {
        let mut e = self.parse_simple();
        while self.peek(0) == Token::Dot {
            let start = e.span().start;
            self.bump();
            let path = self.parse_attr_path();
            let mut end = path.last().map(|a| a.span().end).unwrap_or(e.span().end);
            let default = if self.peek(0) == Token::KwOr {
                self.bump();
                let def = self.parse_select();
                end = def.span().end;
                Some(Box::new(def))
            } else { None };
            e = Expr::Select { span: start..end, expr: Box::new(e), path, default };
        }
        e
    }

    fn parse_attr_path(&mut self) -> Vec<AttrName> {
        let mut path = Vec::new();
        path.push(self.parse_attr());
        while self.peek(0) == Token::Dot {
            self.bump();
            path.push(self.parse_attr());
        }
        path
    }

    fn parse_attr(&mut self) -> AttrName {
        match self.peek(0) {
            Token::Ident => {
                let id = self.bump();
                let name = self.slice(&id.span).to_string();
                AttrName::Ident { span: id.span.clone(), name }
            }
            // Keywords can sometimes be attr names in certain contexts (e.g. `or`, `true`)
            // We'll accept them as ident names.
            Token::KwOr | Token::KwTrue | Token::KwFalse | Token::KwNull | Token::KwLet
            | Token::KwIn | Token::KwRec | Token::KwWith | Token::KwInherit | Token::KwIf
            | Token::KwThen | Token::KwElse | Token::KwAssert => {
                let tok = self.bump();
                let name = self.slice(&tok.span).to_string();
                AttrName::Ident { span: tok.span.clone(), name }
            }
            Token::StringStart => {
                let start = self.peek_span(0).start;
                self.bump();
                // consume up to StringEnd; simplified, we ignore interpolation for attr-name detection
                let mut parts: Vec<StrPart> = Vec::new();
                let mut simple_val = String::new();
                let mut all_literal = true;
                loop {
                    match self.peek(0) {
                        Token::StringContent => {
                            let lx = self.bump();
                            parts.push(StrPart::Literal(lx.span.clone()));
                            if all_literal {
                                simple_val.push_str(self.slice(&lx.span));
                            }
                        }
                        Token::InterpolStart => {
                            all_literal = false;
                            let start = self.peek_span(0).start;
                            self.bump();
                            let e = self.parse_expr();
                            let end = self.peek_span(0).end;
                            if !self.eat(Token::InterpolEnd) {
                                let sp = self.peek_span(0);
                                self.errors.push(ParseError { span: sp, message: "expected `}` in interpolation".into() });
                            }
                            parts.push(StrPart::Interp(start..end, e));
                        }
                        Token::StringEnd => {
                            let end = self.bump().span.end;
                            if all_literal {
                                return AttrName::Str { span: start..end, value: unescape_string(&simple_val) };
                            } else {
                                // Treat dynamic as an expression
                                let expr = Expr::Str { span: start..end, parts };
                                return AttrName::Dynamic { span: start..end, expr };
                            }
                        }
                        _ => {
                            // unexpected; break
                            break;
                        }
                    }
                }
                AttrName::Str { span: start..start, value: String::new() }
            }
            Token::InterpolStart => {
                let start = self.peek_span(0).start;
                self.bump();
                let e = self.parse_expr();
                let end = self.peek_span(0).end;
                if !self.eat(Token::InterpolEnd) {
                    let sp = self.peek_span(0);
                    self.errors.push(ParseError { span: sp, message: "expected `}` in interpolation".into() });
                }
                AttrName::Dynamic { span: start..end, expr: e }
            }
            _ => {
                let sp = self.peek_span(0);
                self.errors.push(ParseError { span: sp.clone(), message: "expected attribute name".into() });
                AttrName::Ident { span: sp.clone(), name: String::new() }
            }
        }
    }

    fn parse_simple(&mut self) -> Expr {
        let start = self.peek_span(0).start;
        match self.peek(0) {
            Token::Integer | Token::Float | Token::Path | Token::Uri | Token::SearchPath => {
                let lx = self.bump();
                Expr::Literal(lx.span.clone())
            }
            Token::KwTrue | Token::KwFalse | Token::KwNull => {
                let lx = self.bump();
                Expr::Literal(lx.span.clone())
            }
            Token::Ident => {
                let lx = self.bump();
                let name = self.slice(&lx.span).to_string();
                Expr::Ident { span: lx.span.clone(), name }
            }
            Token::StringStart => self.parse_string(),
            Token::IndentStart => self.parse_string(),
            Token::LParen => {
                self.bump();
                let e = self.parse_expr();
                if !self.eat(Token::RParen) {
                    let sp = self.peek_span(0);
                    self.errors.push(ParseError { span: sp, message: "expected `)`".into() });
                }
                let end = self.tokens.get(self.pos.saturating_sub(1)).map(|l| l.span.end).unwrap_or(e.span().end);
                Expr::Paren { span: start..end, expr: Box::new(e) }
            }
            Token::LBrack => {
                self.bump();
                let mut elems = Vec::new();
                while !matches!(self.peek(0), Token::RBrack | Token::Eof) {
                    // each element is a select (no application)
                    let e = self.parse_select();
                    elems.push(e);
                }
                let rb = self.bump(); // rbrack
                Expr::List { span: start..rb.span.end, elements: elems }
            }
            Token::KwRec => {
                let rec_kw = self.bump();
                if !matches!(self.peek(0), Token::LBrace) {
                    let sp = self.peek_span(0);
                    self.errors.push(ParseError { span: sp, message: "expected `{` after rec".into() });
                }
                self.eat(Token::LBrace);
                let bindings = self.parse_bindings_until(Token::RBrace);
                let rb = self.bump();
                Expr::AttrSet { span: start..rb.span.end, rec: true, rec_kw_span: Some(rec_kw.span.clone()), bindings }
            }
            Token::LBrace => {
                self.bump();
                let bindings = self.parse_bindings_until(Token::RBrace);
                let rb = self.bump();
                Expr::AttrSet { span: start..rb.span.end, rec: false, rec_kw_span: None, bindings }
            }
            Token::KwLet => {
                // `let` at this level must be `let {...}` - legacy
                // But in standard code, `let` also appears as function; however we shouldn't reach here.
                // fallthrough to let expression
                self.parse_function()
            }
            _ => {
                let sp = self.peek_span(0);
                self.errors.push(ParseError { span: sp.clone(), message: "unexpected token".into() });
                let lx = self.bump();
                Expr::Error(lx.span)
            }
        }
    }

    fn parse_string(&mut self) -> Expr {
        let start = self.peek_span(0).start;
        let is_indent = self.peek(0) == Token::IndentStart;
        self.bump();
        let mut parts: Vec<StrPart> = Vec::new();
        loop {
            match self.peek(0) {
                Token::StringContent => {
                    let lx = self.bump();
                    parts.push(StrPart::Literal(lx.span.clone()));
                }
                Token::InterpolStart => {
                    let interp_start = self.peek_span(0).start;
                    self.bump();
                    let e = self.parse_expr();
                    let interp_end;
                    if self.peek(0) == Token::InterpolEnd {
                        interp_end = self.peek_span(0).end;
                        self.bump();
                    } else {
                        interp_end = self.peek_span(0).end;
                    }
                    parts.push(StrPart::Interp(interp_start..interp_end, e));
                }
                Token::StringEnd | Token::IndentEnd => {
                    let end = self.bump().span.end;
                    return Expr::Str { span: start..end, parts };
                }
                Token::Eof => {
                    let end = self.src.len();
                    return Expr::Str { span: start..end, parts };
                }
                _ => {
                    // unexpected; skip
                    self.bump();
                }
            }
        }
    }

    fn parse_bindings_until(&mut self, end: Token) -> Vec<Binding> {
        let mut bindings = Vec::new();
        loop {
            let tok = self.peek(0);
            if tok == end || tok == Token::Eof {
                break;
            }
            if tok == Token::KwInherit {
                let start = self.peek_span(0).start;
                self.bump();
                let from = if self.peek(0) == Token::LParen {
                    self.bump();
                    let e = self.parse_expr();
                    self.eat(Token::RParen);
                    Some(e)
                } else {
                    None
                };
                let mut attrs = Vec::new();
                while !matches!(self.peek(0), Token::Semicolon | Token::Eof) && self.peek(0) != end {
                    // parse attr
                    attrs.push(self.parse_attr());
                }
                let sp_end = self.peek_span(0).end;
                self.eat(Token::Semicolon);
                bindings.push(Binding {
                    kind: BindingKind::Inherit { from, attrs },
                    span: start..sp_end,
                });
                continue;
            }
            // Normal binding: attrpath = expr ;
            let start = self.peek_span(0).start;
            let path = self.parse_attr_path();
            if !self.eat(Token::Assign) {
                let sp = self.peek_span(0);
                self.errors.push(ParseError { span: sp.clone(), message: "expected `=` in binding".into() });
                // skip to semicolon or end
                while !matches!(self.peek(0), Token::Semicolon | Token::Eof) && self.peek(0) != end {
                    self.bump();
                }
                self.eat(Token::Semicolon);
                continue;
            }
            let value = self.parse_expr();
            let sp_end = self.peek_span(0).end;
            self.eat(Token::Semicolon);
            bindings.push(Binding {
                kind: BindingKind::AttrBinding { path, value },
                span: start..sp_end,
            });
        }
        bindings
    }
}

fn unescape_string(s: &str) -> String {
    // Minimal unescape for attribute keys - keep as-is for now
    s.to_string()
}
