// Dead code analysis for Nix AST

use crate::ast::*;
use std::ops::Range;

#[derive(Debug, Clone)]
pub struct Report {
    pub column: usize,
    pub end_column: usize,
    pub line: usize,
    pub message: String,
    // For edit mode, the span to remove
    pub span: Range<usize>,
    pub kind: ReportKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReportKind {
    UnusedLetBinding,
    UnusedLambdaArg,
    UnusedLambdaPattern,
    UnusedLambdaAtBinding,
    UsedLetBinding, // with -W
    UsedLambdaPattern, // with -W
    UsedLambdaArg, // with -W
}

#[derive(Debug, Clone, Copy)]
pub struct Settings {
    pub no_lambda_arg: bool,
    pub no_lambda_pattern_names: bool,
    pub no_underscore: bool,
    pub warn_used_underscore: bool,
}

pub struct Analyzer<'a> {
    src: &'a [u8],
    settings: Settings,
    skip_lines: Vec<usize>, // lines where the binding on the next line should be skipped
}

#[derive(Debug)]
struct Declaration {
    name: String,
    // Position of the identifier (for diagnostic)
    ident_span: Range<usize>,
    // Span to remove for edit (NOT yet used here directly)
    used: bool,
    kind: DeclKind,
}

#[derive(Debug, Clone, Copy)]
enum DeclKind {
    LetBinding,
    LambdaArg,
    LambdaPattern,
    LambdaAtBinding,
}

struct Scope {
    decls: Vec<Declaration>,
}

pub struct Analyzed {
    pub reports: Vec<Report>,
    pub decls_all: Vec<(Declaration2, DeclKind)>,
}

#[derive(Debug, Clone)]
pub struct Declaration2 {
    pub name: String,
    pub ident_span: Range<usize>,
    pub used: bool,
    // Span to delete in edit mode
    pub delete_span: Range<usize>,
    // For in-pattern editing, additional info
    pub edit_kind: EditKind,
}

#[derive(Debug, Clone)]
pub enum EditKind {
    // Delete the span entirely (for let bindings, lambda pattern entries with sep, inherit attrs)
    Delete,
    // Replace the span with the provided text (for lambda idents rewritten to `_x`)
    RenameUnderscore,
    // Delete the `@binding` pattern prefix/suffix
    DeleteAtBinding,
}

impl<'a> Analyzer<'a> {
    pub fn new(src: &'a [u8], settings: Settings) -> Self {
        // Pre-compute skip lines based on # deadnix: skip comments
        let skip_lines = find_skip_lines(src);
        Analyzer { src, settings, skip_lines }
    }

    pub fn analyze(&self, expr: &Expr) -> Analyzed {
        let mut ctx = AnalyzeCtx {
            src: self.src,
            settings: &self.settings,
            skip_lines: &self.skip_lines,
            scopes: Vec::new(),
            reports: Vec::new(),
            all_decls: Vec::new(),
        };
        ctx.visit_expr(expr);
        // Process remaining scopes
        ctx.finish();
        Analyzed { reports: ctx.reports, decls_all: ctx.all_decls }
    }
}

fn find_skip_lines(src: &[u8]) -> Vec<usize> {
    // Find all lines containing "# deadnix: skip"
    // Return the line numbers where bindings should be skipped (line-after-comment)
    let mut out = Vec::new();
    let mut line = 1usize;
    let mut i = 0;
    while i < src.len() {
        if src[i] == b'#' {
            // scan to end of line
            let mut j = i + 1;
            while j < src.len() && src[j] != b'\n' {
                j += 1;
            }
            let comment = std::str::from_utf8(&src[i..j]).unwrap_or("");
            // Normalize: "# deadnix: skip"
            let trimmed = comment.trim_start_matches('#').trim();
            if trimmed == "deadnix: skip" {
                // The binding on the next line should be skipped
                out.push(line + 1);
            }
            i = j;
            continue;
        }
        if src[i] == b'\n' {
            line += 1;
        }
        i += 1;
    }
    out
}

struct AnalyzeCtx<'a, 'b> {
    src: &'a [u8],
    settings: &'b Settings,
    skip_lines: &'b [usize],
    scopes: Vec<ScopeF>,
    reports: Vec<Report>,
    all_decls: Vec<(Declaration2, DeclKind)>,
}

#[derive(Debug)]
struct ScopeF {
    decls: Vec<DeclF>,
}

#[derive(Debug)]
struct DeclF {
    name: String,
    ident_span: Range<usize>,
    used: bool,
    kind: DeclKind,
    delete_span: Range<usize>,
    edit_kind: EditKind,
    // For skip pragma
    skip: bool,
}

impl<'a, 'b> AnalyzeCtx<'a, 'b> {
    fn line_of(&self, pos: usize) -> usize {
        let mut line = 1;
        for i in 0..pos.min(self.src.len()) {
            if self.src[i] == b'\n' { line += 1; }
        }
        line
    }

    fn col_of(&self, pos: usize) -> usize {
        let mut col = 1;
        for i in (0..pos.min(self.src.len())).rev() {
            if self.src[i] == b'\n' { break; }
            col += 1;
        }
        col
    }

    fn finish(&mut self) {
        // Pop all scopes and emit reports
        while !self.scopes.is_empty() {
            self.pop_scope();
        }
    }

    fn push_scope(&mut self) {
        self.scopes.push(ScopeF { decls: Vec::new() });
    }

    fn pop_scope(&mut self) {
        let scope = self.scopes.pop().unwrap();
        for decl in scope.decls {
            let name = &decl.name;

            // Skip if pragma
            if decl.skip { 
                self.all_decls.push(( 
                    Declaration2 { name: decl.name.clone(), ident_span: decl.ident_span.clone(), used: decl.used, delete_span: decl.delete_span.clone(), edit_kind: decl.edit_kind.clone() }, 
                    decl.kind 
                ));
                continue; 
            }

            // Skip _ idents if settings
            if self.settings.no_underscore && name.starts_with('_') {
                self.all_decls.push(( 
                    Declaration2 { name: decl.name.clone(), ident_span: decl.ident_span.clone(), used: decl.used, delete_span: decl.delete_span.clone(), edit_kind: decl.edit_kind.clone() }, 
                    decl.kind 
                ));
                continue;
            }

            // Determine whether to report this
            let mut report = None;

            match decl.kind {
                DeclKind::LambdaArg => {
                    // Skip if --no-lambda-arg
                    if self.settings.no_lambda_arg {
                        // still push decls (with used=decl.used)
                    } else if !decl.used {
                        if !name.starts_with('_') {
                            let line = self.line_of(decl.ident_span.start);
                            let col = self.col_of(decl.ident_span.start);
                            let end_col = self.col_of(decl.ident_span.end);
                            report = Some(Report {
                                line, column: col, end_column: end_col,
                                message: format!("Unused lambda argument: {}", name),
                                span: decl.ident_span.clone(),
                                kind: ReportKind::UnusedLambdaArg,
                            });
                        }
                    } else if self.settings.warn_used_underscore && name.starts_with('_') {
                        let line = self.line_of(decl.ident_span.start);
                        let col = self.col_of(decl.ident_span.start);
                        let end_col = self.col_of(decl.ident_span.end);
                        report = Some(Report {
                            line, column: col, end_column: end_col,
                            message: format!("Used lambda argument: {}", name),
                            span: decl.ident_span.clone(),
                            kind: ReportKind::UsedLambdaArg,
                        });
                    }
                }
                DeclKind::LambdaPattern => {
                    if self.settings.no_lambda_pattern_names {
                        // Skip (but still push to decls)
                    } else if !decl.used {
                        let line = self.line_of(decl.ident_span.start);
                        let col = self.col_of(decl.ident_span.start);
                        let end_col = self.col_of(decl.ident_span.end);
                        report = Some(Report {
                            line, column: col, end_column: end_col,
                            message: format!("Unused lambda pattern: {}", name),
                            span: decl.ident_span.clone(),
                            kind: ReportKind::UnusedLambdaPattern,
                        });
                    } else if self.settings.warn_used_underscore && name.starts_with('_') {
                        let line = self.line_of(decl.ident_span.start);
                        let col = self.col_of(decl.ident_span.start);
                        let end_col = self.col_of(decl.ident_span.end);
                        report = Some(Report {
                            line, column: col, end_column: end_col,
                            message: format!("Used lambda pattern: {}", name),
                            span: decl.ident_span.clone(),
                            kind: ReportKind::UsedLambdaPattern,
                        });
                    }
                }
                DeclKind::LambdaAtBinding => {
                    if self.settings.no_lambda_pattern_names {
                        // skip
                    } else if !decl.used {
                        let line = self.line_of(decl.ident_span.start);
                        let col = self.col_of(decl.ident_span.start);
                        let end_col = self.col_of(decl.ident_span.end);
                        report = Some(Report {
                            line, column: col, end_column: end_col,
                            message: format!("Unused lambda pattern: {}", name),
                            span: decl.ident_span.clone(),
                            kind: ReportKind::UnusedLambdaAtBinding,
                        });
                    } else if self.settings.warn_used_underscore && name.starts_with('_') {
                        let line = self.line_of(decl.ident_span.start);
                        let col = self.col_of(decl.ident_span.start);
                        let end_col = self.col_of(decl.ident_span.end);
                        report = Some(Report {
                            line, column: col, end_column: end_col,
                            message: format!("Used lambda pattern: {}", name),
                            span: decl.ident_span.clone(),
                            kind: ReportKind::UsedLambdaPattern,
                        });
                    }
                }
                DeclKind::LetBinding => {
                    if !decl.used {
                        let line = self.line_of(decl.ident_span.start);
                        let col = self.col_of(decl.ident_span.start);
                        let end_col = self.col_of(decl.ident_span.end);
                        report = Some(Report {
                            line, column: col, end_column: end_col,
                            message: format!("Unused let binding: {}", name),
                            span: decl.ident_span.clone(),
                            kind: ReportKind::UnusedLetBinding,
                        });
                    } else if self.settings.warn_used_underscore && name.starts_with('_') {
                        let line = self.line_of(decl.ident_span.start);
                        let col = self.col_of(decl.ident_span.start);
                        let end_col = self.col_of(decl.ident_span.end);
                        report = Some(Report {
                            line, column: col, end_column: end_col,
                            message: format!("Used let binding: {}", name),
                            span: decl.ident_span.clone(),
                            kind: ReportKind::UsedLetBinding,
                        });
                    }
                }
            }

            if let Some(r) = report {
                self.reports.push(r);
            }
            self.all_decls.push(( 
                Declaration2 { name: decl.name.clone(), ident_span: decl.ident_span.clone(), used: decl.used, delete_span: decl.delete_span.clone(), edit_kind: decl.edit_kind.clone() }, 
                decl.kind 
            ));
        }
    }

    fn lookup(&mut self, name: &str) -> bool {
        // Walk scopes from innermost to outermost
        for scope in self.scopes.iter_mut().rev() {
            for decl in scope.decls.iter_mut().rev() {
                if decl.name == name {
                    decl.used = true;
                    return true;
                }
            }
        }
        false
    }

    fn add_decl(&mut self, name: String, ident_span: Range<usize>, kind: DeclKind, delete_span: Range<usize>, edit_kind: EditKind) {
        let line = self.line_of(ident_span.start);
        let skip = self.skip_lines.contains(&line);
        self.scopes.last_mut().expect("scope").decls.push(DeclF {
            name, ident_span, used: false, kind, delete_span, edit_kind, skip,
        });
    }

    fn visit_expr(&mut self, expr: &Expr) {
        match expr {
            Expr::Literal(_) => {}
            Expr::Str { parts, .. } => {
                for p in parts {
                    if let StrPart::Interp(_, e) = p {
                        self.visit_expr(e);
                    }
                }
            }
            Expr::Ident { name, .. } => {
                self.lookup(name);
            }
            Expr::Let { bindings, body, .. } => {
                // Introduce a new scope with all bindings (mutually recursive)
                self.push_scope();
                self.collect_bindings_as_decls(bindings, true);
                // Visit binding values (can reference each other)
                for b in bindings {
                    match &b.kind {
                        BindingKind::AttrBinding { value, path } => {
                            // For nested paths (a.b = ...), only `a` is the binding; `b` is inside
                            // For now, visit the value.
                            // We also need to visit dynamic attr names
                            for attr in path {
                                if let AttrName::Dynamic { expr, .. } = attr {
                                    self.visit_expr(expr);
                                }
                            }
                            self.visit_expr(value);
                        }
                        BindingKind::Inherit { from, attrs } => {
                            if let Some(e) = from {
                                self.visit_expr(e);
                            }
                            // `inherit a` => this effectively references the outer scope's `a`
                            // `inherit (e) a` => references e.a
                            if from.is_none() {
                                // Look up each inherited name in outer scope
                                for attr in attrs {
                                    if let Some((_, nm)) = attr.as_ident() {
                                        self.lookup(nm);
                                    }
                                }
                            }
                            for attr in attrs {
                                if let AttrName::Dynamic { expr, .. } = attr {
                                    self.visit_expr(expr);
                                }
                            }
                        }
                    }
                }
                // Visit body
                self.visit_expr(body);
                self.pop_scope();
            }
            Expr::AttrSet { bindings, rec, .. } => {
                if *rec {
                    self.push_scope();
                    self.collect_bindings_as_decls(bindings, true);
                    for b in bindings {
                        match &b.kind {
                            BindingKind::AttrBinding { value, path } => {
                                for attr in path {
                                    if let AttrName::Dynamic { expr, .. } = attr {
                                        self.visit_expr(expr);
                                    }
                                }
                                self.visit_expr(value);
                            }
                            BindingKind::Inherit { from, attrs } => {
                                if let Some(e) = from { self.visit_expr(e); }
                                // inherit without from in rec doesn't count as recursive decl for us; it is just a binding that might shadow outer
                                if from.is_none() {
                                    for attr in attrs {
                                        if let Some((_, nm)) = attr.as_ident() {
                                            self.lookup(nm);
                                        }
                                    }
                                }
                                for attr in attrs {
                                    if let AttrName::Dynamic { expr, .. } = attr {
                                        self.visit_expr(expr);
                                    }
                                }
                            }
                        }
                    }
                    // But we never report rec-set attrs as unused because they're "exported"
                    // Just pop without emitting reports (mark all as used)
                    if let Some(sc) = self.scopes.last_mut() {
                        for d in sc.decls.iter_mut() {
                            d.used = true;
                        }
                    }
                    self.pop_scope();
                } else {
                    // Non-rec attrset: bindings are not in scope among themselves
                    for b in bindings {
                        match &b.kind {
                            BindingKind::AttrBinding { value, path } => {
                                for attr in path {
                                    if let AttrName::Dynamic { expr, .. } = attr {
                                        self.visit_expr(expr);
                                    }
                                }
                                self.visit_expr(value);
                            }
                            BindingKind::Inherit { from, attrs } => {
                                if let Some(e) = from { self.visit_expr(e); }
                                if from.is_none() {
                                    for attr in attrs {
                                        if let Some((_, nm)) = attr.as_ident() {
                                            self.lookup(nm);
                                        }
                                    }
                                }
                                for attr in attrs {
                                    if let AttrName::Dynamic { expr, .. } = attr {
                                        self.visit_expr(expr);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            Expr::List { elements, .. } => {
                for e in elements { self.visit_expr(e); }
            }
            Expr::Lambda { param, body, .. } => {
                self.push_scope();
                // Add declarations from param
                match &param.kind {
                    ParamKind::Ident { span, name } => {
                        self.add_decl(name.clone(), span.clone(), DeclKind::LambdaArg, span.clone(), EditKind::RenameUnderscore);
                    }
                    ParamKind::Pattern { at_binding, entries, .. } => {
                        if let Some(ab) = at_binding {
                            self.add_decl(ab.name.clone(), ab.ident_span.clone(), DeclKind::LambdaAtBinding, ab.full_span.clone(), EditKind::DeleteAtBinding);
                        }
                        for (i, e) in entries.iter().enumerate() {
                            // edit span: if removing this entry, we need to remove the ident + optional default + the appropriate separator
                            let del_span = if entries.len() == 1 {
                                // only entry: remove just the entry itself (no comma)
                                e.span.clone()
                            } else if i + 1 < entries.len() {
                                // not last: remove this entry + trailing comma + following ws
                                e.span_with_sep.clone()
                            } else {
                                // last: remove preceding comma + this entry
                                e.span_with_prev_sep.clone()
                            };
                            self.add_decl(e.name.clone(), e.ident_span.clone(), DeclKind::LambdaPattern, del_span, EditKind::Delete);
                        }
                    }
                }
                // Visit defaults (they can reference other pattern entries)
                if let ParamKind::Pattern { entries, .. } = &param.kind {
                    for e in entries {
                        if let Some(def) = &e.default {
                            self.visit_expr(def);
                        }
                    }
                }
                self.visit_expr(body);
                self.pop_scope();
            }
            Expr::Apply { func, arg, .. } => {
                self.visit_expr(func);
                self.visit_expr(arg);
            }
            Expr::Select { expr, path, default, .. } => {
                self.visit_expr(expr);
                for a in path {
                    if let AttrName::Dynamic { expr, .. } = a {
                        self.visit_expr(expr);
                    }
                }
                if let Some(d) = default {
                    self.visit_expr(d);
                }
            }
            Expr::BinOp { lhs, rhs, .. } => {
                self.visit_expr(lhs);
                self.visit_expr(rhs);
            }
            Expr::UnaryOp { expr, .. } => {
                self.visit_expr(expr);
            }
            Expr::If { cond, then_branch, else_branch, .. } => {
                self.visit_expr(cond);
                self.visit_expr(then_branch);
                self.visit_expr(else_branch);
            }
            Expr::With { expr, body, .. } => {
                self.visit_expr(expr);
                self.visit_expr(body);
            }
            Expr::Assert { cond, body, .. } => {
                self.visit_expr(cond);
                self.visit_expr(body);
            }
            Expr::HasAttr { expr, path, .. } => {
                self.visit_expr(expr);
                for a in path {
                    if let AttrName::Dynamic { expr, .. } = a {
                        self.visit_expr(expr);
                    }
                }
            }
            Expr::Paren { expr, .. } => self.visit_expr(expr),
            Expr::Error(_) => {}
        }
    }

    fn collect_bindings_as_decls(&mut self, bindings: &[Binding], _recursive: bool) {
        for b in bindings {
            match &b.kind {
                BindingKind::AttrBinding { path, .. } => {
                    if let Some(first) = path.first() {
                        if path.len() == 1 {
                            if let Some((span, name)) = first.as_ident() {
                                // Delete span = entire binding (from start to end including ;)
                                self.add_decl(name.to_string(), span.clone(), DeclKind::LetBinding, b.span.clone(), EditKind::Delete);
                            }
                        } else {
                            // a.b = value -- `a` is bound but we don't track multi-level attrpath
                            // This is for `let a.b = 1; in ...` which sets a to { b = 1; }
                            // For our analysis, we just skip.
                        }
                    }
                }
                BindingKind::Inherit { attrs, from } => {
                    for attr in attrs {
                        if let Some((span, name)) = attr.as_ident() {
                            // Delete span: just this attr name; for single-attr inherit, the entire binding
                            let del_span = if attrs.len() == 1 {
                                b.span.clone()
                            } else {
                                // need to also remove surrounding whitespace/sep... simple: just span
                                span.clone()
                            };
                            let _ = from;
                            self.add_decl(name.to_string(), span.clone(), DeclKind::LetBinding, del_span, EditKind::Delete);
                        }
                    }
                }
            }
        }
    }
}
