                self.all_decls.push(( 
                    Declaration2 { name: decl.name.clone(), ident_span: decl.ident_span.clone(), used: decl.used, delete_span: decl.delete_span.clone(), edit_kind: decl.edit_kind.clone() }, 
                    decl.kind 
