                    if self.settings.no_lambda_pattern_names {
                        // Skip (but still push to decls)
                    } else if !decl.used {
                        let line = self.line_of(decl.ident_span.start);
                        let col = self.col_of(decl.ident_span.start);
                        let end_col = self.col_of(decl.ident_span.end);
                        report = Some(Report {
                            line, column: col, end_column: end_col,
                            message: format!("Unused lambda pattern: {}", name),
                            span: decl.ident_span.clone(),
                            kind: ReportKind::UnusedLambdaPattern,
                        });
                    } else if self.settings.warn_used_underscore && name.starts_with('_') {
                        let line = self.line_of(decl.ident_span.start);
                        let col = self.col_of(decl.ident_span.start);
                        let end_col = self.col_of(decl.ident_span.end);
                        report = Some(Report {
                            line, column: col, end_column: end_col,
