}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReportKind {
    UnusedLetBinding,
    UnusedLambdaArg,
    UnusedLambdaPattern,
    UnusedLambdaAtBinding,
    UsedLetBinding, // with -W
    UsedLambdaPattern, // with -W
    UsedLambdaArg, // with -W
}

#[derive(Debug, Clone, Copy)]
pub struct Settings {
    pub no_lambda_arg: bool,
    pub no_lambda_pattern_names: bool,
    pub no_underscore: bool,
    pub warn_used_underscore: bool,
}

pub struct Analyzer<'a> {
    src: &'a [u8],
    settings: Settings,
    skip_lines: Vec<usize>, // lines where the binding on the next line should be skipped
}

#[derive(Debug)]
struct Declaration {
