// Report formatting

use crate::analyzer::Report;

pub struct RenderOptions {
    pub no_color: bool,
}

pub fn sort_reports(reports: &mut Vec<Report>) {
    reports.sort_by_key(|r| (r.line, r.column, r.end_column, r.message.clone()));
}

pub fn format_human(file: &str, reports: &[Report], src: &str, no_color: bool) -> String {
    if reports.is_empty() { return String::new(); }
    let mut out = String::new();
    // Header: "Warning: Unused declarations were found."
    if no_color {
        out.push_str("Warning: Unused declarations were found.\n");
    } else {
        out.push_str("\u{1b}[33mWarning:\u{1b}[0m Unused declarations were found.\n");
    }

    // Find max line number to determine column width
    let max_line = reports.iter().map(|r| r.line).max().unwrap_or(1);
    let line_width = max_line.to_string().len();
    // Prefix: (line_width + 2) spaces + '│'
    let prefix_pad = line_width + 2;

    // Write header with the file location info: "   ╭─[file:line:col]"
    let first = &reports[0];
    {
        let mut line_str = String::new();
        line_str.push_str(&" ".repeat(prefix_pad));
        if no_color {
            line_str.push_str("╭─[");
        } else {
            line_str.push_str("\u{1b}[38;5;246m╭\u{1b}[0m\u{1b}[38;5;246m─\u{1b}[0m\u{1b}[38;5;246m[\u{1b}[0m");
        }
        line_str.push_str(&format!("{}:{}:{}", file, first.line, first.column));
        if no_color {
            line_str.push(']');
        } else {
            line_str.push_str("\u{1b}[38;5;246m]\u{1b}[0m");
        }
        line_str.push('\n');
        out.push_str(&line_str);
    }

    // Now group reports by line
    let lines: Vec<&str> = src.lines().collect();
    let mut by_line: Vec<(usize, Vec<&Report>)> = Vec::new();
    let mut cur_line = 0;
    for r in reports {
        if let Some((l, v)) = by_line.last_mut() {
            if *l == r.line {
                v.push(r);
                continue;
            }
        }
        by_line.push((r.line, vec![r]));
        cur_line = r.line;
    }
    let _ = cur_line;

    // We won't try color for inline source chars exactly; just output simpler form with/without color.
    // NO_COLOR output closely matches the binary's no-color form.

    for (line_no, reps) in &by_line {
        // Print source line: " N │<source_line>"
        let line_src = lines.get(line_no - 1).copied().unwrap_or("");
        let line_num_str = format!("{:>width$}", line_no, width = line_width);
        let mut data_prefix = String::new();
        data_prefix.push(' ');
        data_prefix.push_str(&line_num_str);
        data_prefix.push(' ');
        if no_color {
