                } else {
                    line.push_str("\u{1b}[35m─\u{1b}[0m");
                }
                cur += 1;
            }
            // space at msg_col - 1
            line.push(' ');
            line.push_str(&r.message);
            line.push('\n');
            out.push_str(&line);
        }
    }

