        s.push('{');
        s.push_str("\"column\":");
        s.push_str(&r.column.to_string());
        s.push_str(",\"endColumn\":");
        s.push_str(&r.end_column.to_string());
        s.push_str(",\"line\":");
        s.push_str(&r.line.to_string());
        s.push_str(",\"message\":");
        push_json_string(&mut s, &r.message);
        s.push('}');
    }
    s.push_str("]}");
    s
}

fn push_json_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
