                line.push_str("\u{1b}[38;5;240m");
                line.push_str(&rail_content);
                line.push_str("\u{1b}[0m");
            }

            let pointer_col = (r.column + r.end_column) / 2;

            // Residual bars at positions of reports after current in sorted list
            let mut remaining: Vec<(usize, ReportKind)> = sorted[i+1..].iter().map(|x| ((x.column + x.end_column) / 2, x.kind)).collect();
            remaining.sort_by_key(|x| x.0);

