                        // -o VAL: consume next arg as output format
                        // or -oVAL inline
                        if j + 1 < bytes.len() {
                            let val = &a[j+1..];
                            match val {
                                "human-readable" => args.output_format = OutputFormat::Human,
                                "json" => args.output_format = OutputFormat::Json,
                                other => return ParseCliResult { args, error: Some(format!("invalid output format: {}", other)) },
                            }
                            // Skip to end of this arg
                            j = bytes.len();
                        } else {
                            if i + 1 >= argv.len() {
                                return ParseCliResult { args, error: Some("-o requires an argument".into()) };
                            }
                            match argv[i+1].as_str() {
                                "human-readable" => args.output_format = OutputFormat::Human,
                                "json" => args.output_format = OutputFormat::Json,
                                other => return ParseCliResult { args, error: Some(format!("invalid output format: {}", other)) },
                            }
                            i += 1;
                        }
                    }
                    _ => return ParseCliResult { args, error: Some(format!("unknown short option: -{}", c as char)) },
                }
                j += 1;
            }
            i += 1;
            continue;
        }
        // Positional
        args.paths.push(a.clone());
        i += 1;
    }
    ParseCliResult { args, error: None }
}

