use crate::analyzer::{Declaration2, EditKind};
use crate::ast::*;
use std::ops::Range;

pub struct EditPlan {
    // List of edits: (range to remove/replace, replacement text)
    pub edits: Vec<(Range<usize>, String)>,
}

pub fn plan_edits(
    decls: &[(Declaration2, crate::analyzer::DeclKind)],
    src: &[u8],
    no_lambda_arg: bool,
    no_lambda_pattern_names: bool,
    no_underscore: bool,
) -> Vec<(Range<usize>, String)> {
