                // Delete the whole binding (including trailing newline/whitespace)
                let r = expand_binding_delete(src, &d.delete_span);
                edits.push((r, String::new()));
            }
            DeclKind::LambdaArg => {
                if no_lambda_arg { continue; }
                if d.name.starts_with('_') { continue; }
                // Rename to _name
                edits.push((d.ident_span.clone(), format!("_{}", d.name)));
            }
            DeclKind::LambdaPattern => {
                if no_lambda_pattern_names { continue; }
                // Delete pattern entry (with surrounding separator)
                edits.push((d.delete_span.clone(), String::new()));
            }
            DeclKind::LambdaAtBinding => {
                if no_lambda_pattern_names { continue; }
                // Delete @binding
                edits.push((d.delete_span.clone(), String::new()));
            }
        }
    }
    edits
}

// For let binding: include trailing whitespace up to and including the newline
fn expand_binding_delete(src: &[u8], span: &Range<usize>) -> Range<usize> {
    let mut end = span.end;
    // Include trailing whitespace and newline (but only one newline)
    while end < src.len() && (src[end] == b' ' || src[end] == b'\t') {
        end += 1;
    }
    if end < src.len() && src[end] == b'\r' {
        end += 1;
    }
    if end < src.len() && src[end] == b'\n' {
        end += 1;
    }
    // Also include leading whitespace on the same line? For let bindings, the span
    // typically includes them via attrpath start... but preceding whitespace on the same line
    // needs removal too.
    // For now, include leading whitespace on the same line if line is otherwise empty after removal.
    let mut start = span.start;
    while start > 0 && (src[start - 1] == b' ' || src[start - 1] == b'\t') {
        start -= 1;
    }
    start..end
}

pub fn apply_edits(src: &[u8], edits: &mut Vec<(Range<usize>, String)>) -> Vec<u8> {
    // Sort by start; merge overlapping
    edits.sort_by_key(|e| e.0.start);
    let mut out = Vec::new();
    let mut cursor = 0usize;
    for (r, rep) in edits {
        if r.start < cursor {
            continue; // overlap; skip
        }
        out.extend_from_slice(&src[cursor..r.start]);
        out.extend_from_slice(rep.as_bytes());
        cursor = r.end;
    }
    out.extend_from_slice(&src[cursor..]);
    out
}
