mod lexer;
mod parser;
mod ast;
mod analyzer;
mod report;
mod cli;
mod edit;

use std::io::Write;
use std::path::{Path, PathBuf};
use std::fs;
use parser::Parser;
use analyzer::{Analyzer, Settings};
use report::{format_human, format_json, sort_reports};
use cli::{parse_cli, OutputFormat, HELP, VERSION};

fn main() {
    let args_iter: Vec<String> = std::env::args().skip(1).collect();
    let parse_res = parse_cli(args_iter);
    if let Some(err) = parse_res.error {
        eprintln!("error: {}", err);
        std::process::exit(2);
    }
    let args = parse_res.args;
    if args.help {
        print!("{}", HELP);
        return;
    }
    if args.version {
        println!("{}", VERSION);
        return;
    }

    let paths: Vec<String> = if args.paths.is_empty() {
        vec![".".to_string()]
    } else {
        args.paths.clone()
    };

    let settings = Settings {
        no_lambda_arg: args.no_lambda_arg,
        no_lambda_pattern_names: args.no_lambda_pattern_names,
        no_underscore: args.no_underscore,
        warn_used_underscore: args.warn_used_underscore,
    };
    let no_color = std::env::var("NO_COLOR").is_ok();

    let mut found_issues = false;

    // Collect all files to process
    let mut files: Vec<String> = Vec::new();
    let excludes: Vec<PathBuf> = args.excludes.iter().map(|s| PathBuf::from(s)).collect();
    let excludes_canon: Vec<PathBuf> = excludes.iter().map(|p| canonicalize_rel(p)).collect();

    for path in &paths {
        collect_files(path, args.hidden, &excludes_canon, &mut files);
    }

    for file in &files {
        let src = match fs::read(file) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("Error stating file {}: {}", file, e);
                continue;
            }
        };
        let mut p = Parser::new(&src);
        let expr = p.parse();
        for err in &p.errors {
            eprintln!("Error parsing file {}: {}", file, err.message);
        }
        let analyzer = Analyzer::new(&src, settings);
        let mut analyzed = analyzer.analyze(&expr);
        sort_reports(&mut analyzed.reports);
        if !analyzed.reports.is_empty() {
            found_issues = true;
        }

        let src_str = std::str::from_utf8(&src).unwrap_or("");

        if args.edit {
            // Apply edits
            let mut edits = edit::plan_edits(
                &analyzed.decls_all,
                &src,
                args.no_lambda_arg,
                args.no_lambda_pattern_names,
                args.no_underscore,
            );
            let new_src = edit::apply_edits(&src, &mut edits);
            let _ = fs::write(file, &new_src);
        }

        if !args.quiet {
            match args.output_format {
                OutputFormat::Human => {
                    let out = format_human(file, &analyzed.reports, src_str, no_color);
                    print!("{}", out);
                }
                OutputFormat::Json => {
                    // One JSON object per file, only if there are issues
                    if !analyzed.reports.is_empty() {
                        println!("{}", format_json(file, &analyzed.reports));
                    }
                }
            }
        }
    }

    if args.fail && found_issues {
        std::process::exit(1);
    }
}

fn canonicalize_rel(p: &Path) -> PathBuf {
    // Use path as-is but normalize
    p.to_path_buf()
}

fn path_matches_exclude(p: &Path, excludes: &[PathBuf]) -> bool {
    for e in excludes {
        if paths_equal(p, e) { return true; }
    }
    false
}

fn paths_equal(a: &Path, b: &Path) -> bool {
    let sa: Vec<_> = a.components().collect();
    let sb: Vec<_> = b.components().collect();
    sa == sb
}

fn collect_files(path: &str, hidden: bool, excludes: &[PathBuf], out: &mut Vec<String>) {
    let p = Path::new(path);
    let meta = match fs::metadata(p) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error stating file {}: {}", path, e);
            return;
        }
    };
    if meta.is_file() {
        // Apply exclude check
        if path_matches_exclude(p, excludes) { return; }
        out.push(path.to_string());
        return;
    }
    if meta.is_dir() {
        // Traverse directory
        traverse_dir(p, hidden, excludes, out);
    }
}

fn traverse_dir(p: &Path, hidden: bool, excludes: &[PathBuf], out: &mut Vec<String>) {
    let entries = match fs::read_dir(p) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error reading dir {}: {}", p.display(), e);
            return;
        }
    };
    let mut entries: Vec<_> = entries.filter_map(|e| e.ok()).collect();
    entries.sort_by_key(|e| e.file_name());
    for entry in entries {
        let path = entry.path();
        let name = entry.file_name();
        let name_str = name.to_string_lossy().to_string();
        let is_hidden = name_str.starts_with('.');
        let ft = match entry.file_type() { Ok(t) => t, Err(_) => continue };
        if ft.is_dir() {
            if is_hidden && !hidden { continue; }
            if path_matches_exclude(&path, excludes) { continue; }
            traverse_dir(&path, hidden, excludes, out);
        } else if ft.is_file() {
            // Match *.nix (and .*.nix with hidden flag)
            let is_nix = name_str.ends_with(".nix");
            if !is_nix { continue; }
            // Hidden files like `.foo.nix`
            if is_hidden && !hidden { continue; }
            if path_matches_exclude(&path, excludes) { continue; }
            let s = path.to_string_lossy().to_string();
            out.push(s);
        }
    }
}
