// Edit mode: remove unused bindings from source

use crate::analyzer::{Declaration2, EditKind};
use crate::ast::*;
use std::ops::Range;

pub fn plan_edits(
    decls: &[(Declaration2, crate::analyzer::DeclKind)],
    src: &[u8],
    no_lambda_arg: bool,
    no_lambda_pattern_names: bool,
    no_underscore: bool,
) -> Vec<(Range<usize>, String)> {
    use crate::analyzer::DeclKind;
    let _ = src;
    let mut edits = Vec::new();
    for (d, kind) in decls {
        if d.used { continue; }
        if no_underscore && d.name.starts_with('_') { continue; }
        match kind {
            DeclKind::LetBinding => {
                let r = expand_binding_delete(src, &d.delete_span);
                edits.push((r, String::new()));
            }
            DeclKind::LambdaArg => {
                if no_lambda_arg { continue; }
                if d.name.starts_with('_') { continue; }
                edits.push((d.ident_span.clone(), format!("_{}", d.name)));
            }
            DeclKind::LambdaPattern => {
                if no_lambda_pattern_names { continue; }
                // Only delete if the `span` indicates a removable entry
                // The delete_span already includes the proper separator handling.
                edits.push((d.delete_span.clone(), String::new()));
            }
            DeclKind::LambdaAtBinding => {
                if no_lambda_pattern_names { continue; }
                edits.push((d.delete_span.clone(), String::new()));
            }
        }
    }
    edits
}

fn expand_binding_delete(src: &[u8], span: &Range<usize>) -> Range<usize> {
    let mut end = span.end;
    while end < src.len() && (src[end] == b' ' || src[end] == b'\t') {
        end += 1;
    }
    if end < src.len() && src[end] == b'\r' {
        end += 1;
    }
    if end < src.len() && src[end] == b'\n' {
        end += 1;
    }
    let mut start = span.start;
    while start > 0 && (src[start - 1] == b' ' || src[start - 1] == b'\t') {
        start -= 1;
    }
    start..end
}

pub fn apply_edits(src: &[u8], edits: &mut Vec<(Range<usize>, String)>) -> Vec<u8> {
    edits.sort_by_key(|e| e.0.start);
    // Merge overlapping
    let mut merged: Vec<(Range<usize>, String)> = Vec::new();
    for (r, rep) in edits.drain(..) {
        if let Some(last) = merged.last_mut() {
            if r.start < last.0.end {
                // overlap: extend
                if r.end > last.0.end {
                    last.0.end = r.end;
                }
                // keep first replacement text (ignore new)
                continue;
            }
        }
        merged.push((r, rep));
    }
    let mut out = Vec::new();
    let mut cursor = 0usize;
    for (r, rep) in &merged {
        out.extend_from_slice(&src[cursor..r.start]);
        out.extend_from_slice(rep.as_bytes());
        cursor = r.end;
    }
    out.extend_from_slice(&src[cursor..]);
    out
}
