python3 <<'EOF'
content = open('/workspace/src/lexer.rs').read()
# Always push Interpol context on ${ regardless of outer
old = '''        // ${ - interp start (inside code means not applicable, but handle just in case)
        if c == b'$' && self.peek(1) == Some(b'{') {
            self.pos += 2;
            // If outer is string, push Interpol with matching whitespace
            let ws = match self.ctx_stack.last() {
                Some(&Context::String(ws)) => Some(ws),
                _ => None,
            };
            if let Some(ws) = ws {
                self.ctx_stack.push(Context::Interpol(ws, 0));
            }
            return Lexeme { tok: Token::InterpolStart, span: start..self.pos };
        }'''
new = '''        if c == b'$' && self.peek(1) == Some(b'{') {
            self.pos += 2;
            // Push Interpol context. Use Quote as placeholder ws; for pure code interpolation, closing } pops us back to outer (which is code).
            let ws = match self.ctx_stack.last() {
                Some(&Context::String(ws)) => ws,
                _ => StringCtx::Quote,
            };
            self.ctx_stack.push(Context::Interpol(ws, 0));
            return Lexeme { tok: Token::InterpolStart, span: start..self.pos };
        }'''
content = content.replace(old, new)

# Also, when we pop Interpol, the outer context could be Code or String.
# In the existing code, pop_interpol then stays on outer (string if wrapping, code if not).
# The problem is the closing `}` finds an Interpol context and pops it.
# Previous code: if outer was not String, we didn't push Interpol, so `}` would be RBrace.
# Now we always push, so `}` correctly becomes InterpolEnd.

with open('/workspace/src/lexer.rs','w') as f:
    f.write(content)
EOF

