content = open('/workspace/src/lexer.rs').read()

# Add handling for paths starting with . (./, ../) before checking identifiers
# We need to detect: '.' '/' [pathchar]... or '..' '/' [pathchar]...
# Add after ellipsis check
old = '''        // Ellipsis
        if self.starts_with(b"...") {
            self.pos += 3;
            return Lexeme { tok: Token::Ellipsis, span: start..self.pos };
        }'''
new = '''        // Ellipsis
        if self.starts_with(b"...") {
            self.pos += 3;
            return Lexeme { tok: Token::Ellipsis, span: start..self.pos };
        }

        // Relative path: ./path or ../path
        if c == b'.' && (self.peek(1) == Some(b'/') || (self.peek(1) == Some(b'.') && self.peek(2) == Some(b'/'))) {
            // consume leading .s and /
            while let Some(ch) = self.peek(0) {
                if ch == b'.' { self.pos += 1; } else { break; }
            }
            // now consume /
            if self.peek(0) == Some(b'/') {
                self.pos += 1;
            }
            while let Some(ch) = self.peek(0) {
                if ch.is_ascii_alphanumeric() || matches!(ch, b'_' | b'-' | b'.' | b'+' | b'/') {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            return Lexeme { tok: Token::Path, span: start..self.pos };
        }'''
