// Walk AST to find `let ... in body` where all bindings are unused
// and emit an edit that replaces the whole let with just the body.
pub fn plan_let_elimination(
    expr: &Expr,
    decls: &[(Declaration2, crate::analyzer::DeclKind)],
    src: &[u8],
    no_lambda_arg: bool,
    no_lambda_pattern_names: bool,
    no_underscore: bool,
) -> Vec<(Range<usize>, String)> {
