            DeclKind::LetBinding => true,
            DeclKind::LambdaArg => !no_lambda_arg && !d.name.starts_with('_'),
            DeclKind::LambdaPattern => !no_lambda_pattern_names,
            DeclKind::LambdaAtBinding => !no_lambda_pattern_names,
        };
