            walk_for_empty_let(arg, src, removed, edits);
        }
        Expr::BinOp { lhs, rhs, .. } => {
            walk_for_empty_let(lhs, src, removed, edits);
            walk_for_empty_let(rhs, src, removed, edits);
        }
        Expr::UnaryOp { expr, .. } => walk_for_empty_let(expr, src, removed, edits),
        Expr::If { cond, then_branch, else_branch, .. } => {
